"""Original CNS infections chapter: acute meningitis and encephalitis section."""
from qbank_authoring import question,ref,finalize
ME=ref('WHO Meningitis Diagnosis, Treatment and Care Recommendations, 2025','https://www.ncbi.nlm.nih.gov/books/NBK614844/?report=classic')
