rows=[]
def q(*a,**k):rows.append(question(*a,**k))

q('Acute fever, headache and neck stiffness raise concern for bacterial meningitis. What is the best initial principle?', 'Obtain urgent blood/CSF investigations when safe without delaying indicated empiric antimicrobial treatment',[
 ('Wait for culture confirmation before antibiotics','Delay can worsen outcome.'),('Treat only after every classic symptom appears','The full presentation is not always present.'),('A normal peripheral white count excludes meningitis','It is not an exclusion test.')],
 'Diagnostic speed and treatment speed must be coordinated', '**LP is a central investigation but treatment should not wait for avoidable delays.**', ['Take blood cultures promptly where feasible.','Assess sepsis, airway and LP safety.'], '**Use the clinical context.**', ['Immune status and exposures change the differential.','Continue pathogen-directed reassessment as results return.'], [['Blood cultures','Promptly when feasible'],['LP','As soon as safe'],['Antibiotics','Do not delay unnecessarily']], [ME], 'clinical_scenario')
q('Suspected meningitis is accompanied by markedly reduced consciousness and a new focal neurological deficit. What is the best approach to LP?', 'Defer LP pending appropriate stabilization and imaging assessment, while starting necessary treatment',[
 ('Perform LP immediately regardless of mass-effect risk','The findings require safety assessment.'),('Withhold antibiotics until CT and LP are both completed','Necessary treatment should not be delayed.'),('CT is required before LP in every uncomplicated case','Routine imaging can create unnecessary delays.')],
 'Imaging is selective rather than a universal preliminary step', '**Focal signs, severe consciousness impairment and other risk findings can justify imaging before LP.**', ['Assess procedural contraindications and clinical stability.','A scan is not a substitute for examination.'], '**Protect treatment timing.**', ['Obtain blood cultures and give empiric therapy when LP is deferred.','Perform CSF assessment later when safe and useful.'], [['Uncomplicated presentation','Early LP if safe'],['Risk findings','Image/defer as indicated'],['Deferred LP','Do not defer urgent therapy']], [ME], 'clinical_scenario')
